{
  "evidence": [
    {
      "ref_id": "p004",
      "group_ids": [
        "D1",
        "D2"
      ],
      "quote": "我們堅決守護平等尊重的職場底線,對歧視與騷擾堅持零容忍,嚴禁在工作場所進行任何形式的歧視或騷擾行爲(包 括性騷擾和非性騷擾)。本集團每年至少一次向全體員工開展反歧視和反騷擾培訓,持續打造公平、尊重、包容的工 作氛圍。",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "未明确",
      "scope": "工作场所/全体员工",
      "relevance": "明确披露禁止歧视和骚扰的政策（零容忍）及具体培训措施，符合D1和D2要求。"
    },
    {
      "ref_id": "p001",
      "group_ids": [
        "D3",
        "D4"
      ],
      "quote": "我們鼓勵相關人員在發現任何歧視或騷擾行爲時儘快進行上報,制定《中國生物製藥員工意見反饋及申訴管理制度》, 明確了歧視或騷擾行爲的申訴渠道,堅決保障舉報人權益。",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "未明确",
      "scope": "歧视或骚扰行为",
      "relevance": "明确了针对歧视或骚扰行为的申诉渠道（受理机制）及举报人权益保障（保护措施），符合D3和D4要求。"
    },
    {
      "ref_id": "p003",
      "group_ids": [
        "D5"
      ],
      "quote": "經查實發現歧視、騷擾等不當行爲的,我們將依據《中國生物製藥員工手冊》《中國生物製藥有限公司火爐法則》中 相關規定,根據不當行爲的嚴重程度,對涉事人員執行警告、記過、解雇等處罰,涉嫌違法犯罪者移交司法機關處理。 報告期內,本集團未發生因歧視或騷擾而產生的訴訟案件。",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "2025 年1 月1 日至2025 年12 月31 日",
      "scope": "查实歧视、骚扰等不当行为",
      "relevance": "披露了针对查实歧视或骚扰的具体处分规则（警告、记过、解雇、移交司法），符合D5责任追究要求。"
    }
  ]
}
